import{_ as p,o as a,c as t,a3 as r}from"./chunks/framework.DdpBa4_E.js";const h=JSON.parse('{"title":"赞誉","description":"","frontmatter":{},"headers":[],"relativePath":"books/attached/02-赞誉.md","filePath":"books/attached/02-赞誉.md","lastUpdated":1794298621000}'),o={name:"books/attached/02-赞誉.md"};function n(s,e,i,_,c,l){return a(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="赞誉" tabindex="-1">赞誉 <a class="header-anchor" href="#赞誉" aria-label="Permalink to &quot;赞誉&quot;">​</a></h1><p>这本书中的生活技巧、问卷和案例都十分丰富，通过扎实的研究和精妙的技巧，令人们“让美妙的爱情触手可及”，同时将现行的亲密关系经营得更好。</p><p>——《出版人周刊》（Publishers Weekly)</p><p>这是一本建立完美恋爱关系的实用指南。</p><p>——《科克斯书评》（Kirkus Reviews)</p><p>这是真正的科学，而非将一家之言简单地堆砌起来。作者通过丰富的案例，清楚地阐明了自己的理论。书中对于低质量恋情的避免，以及跳脱亲密关系中周而复始的消极交流，都提出了中肯的建议。书的最后一个部分，深入地阐释了有效沟通和冲突解决。这本书可以说省去了很多心理治疗的费用，同时也让读者更有信心去追求健康、舒适的亲密关系。</p><p>——《新纪元零售商》（New Age Retailer)</p><p>阿米尔·莱文和蕾切尔·赫尔勒的这本著作非常棒：条理清晰、可读性强、眼光独到。不管你是和我一样新开始一段关系，还是已婚二十多年，并且自以为很了解自己的伴侣，这本书都将有助于你。</p><p>——《科学美国人》（Scientific American)这本书重新定义了亲密关系的内涵，极具突破性。</p><p>——《男人来自火星，女人来自金星》</p><p>(Men Are from Mars,Women Are from Venus)作者约翰·格雷（John Gray）</p><p>这本书既好看又有趣，可以帮助人们正确挑选伴侣，令亲密关系变得完满的原因与方法。总之，字里行间都令人愉悦。</p><p>——畅销书《重塑你的人生》（Reinventing Your Life）作者珍妮特·科罗斯科（Janet Klosko）</p><p>那些为老生常谈的问题——“究竟是哪儿不对劲”而困惑的人们，一定能通过这堂依恋理论的速成课而获益良多。</p><p>——《ELLE》杂志</p><p>《灰姑娘》中的王子不惜倾尽国力，只为找到能穿上水晶鞋的那个她，最后两人也幸福地生活在了一起。而这本书则是写给平凡的我们。在这本书中，莱文和赫尔勒将多年心血投入依恋风格研究中，将亲密关系中的自发现象，提炼成为具有操作性、可读性的指南，避免读者陷入捉摸不透的糟糕亲密关系，让我们更加从容地寻找到快意的人生。</p><p>——哈佛大学药学院精神病学教授</p><p>约翰·赫尔曼（John Herman）</p><p>这本书基于作者25年的研究成果，辅之以鲜活而深刻的案例，并且加入了精心设计的有趣案例，这本书所提供的深刻视角和宝贵技巧，能够惠及所有的读者。</p><p>——加州大学戴维斯分校著名心理学教授</p><p>菲利普·谢弗（Phillip Shaver）</p>',21)])])}const m=p(o,[["render",n]]);export{h as __pageData,m as default};
